const fs = require('fs');
const path = require('path');
const http = require('http');

const endpoint = 'http://127.0.0.1:54419/status';
const resultsDir = path.join(__dirname, 'results');
const outputPath = path.join(resultsDir, 'status.json');

if (!fs.existsSync(resultsDir)) {
  fs.mkdirSync(resultsDir, { recursive: true });
}

const request = http.get(endpoint, (res) => {
  const chunks = [];
  res.on('data', (chunk) => chunks.push(chunk));
  res.on('end', () => {
    const body = Buffer.concat(chunks).toString('utf8');
    let parsed;
    try {
      parsed = JSON.parse(body);
    } catch (e) {
      parsed = { raw: body };
    }
    const status = res.statusCode;
    const payload = { status, body: parsed };
    fs.writeFileSync(outputPath, JSON.stringify(payload, null, 2));
    console.log(`status=${status}`);
    console.log(`wrote ${outputPath}`);
  });
});

request.on('error', (err) => {
  const payload = { status: null, error: err.message };
  fs.writeFileSync(outputPath, JSON.stringify(payload, null, 2));
  console.error(`request error: ${err.message}`);
  process.exit(1);
});

